psql "postgresql://postgres@localhost:5432/postgres" <<'SQL'
BEGIN;

-- 1. Rename old table
ALTER TABLE app.events RENAME TO events_old;

-- 2. Create partitioned table with same structure
CREATE TABLE app.events (
  id BIGSERIAL,
  created_at TIMESTAMPTZ NOT NULL,
  event_type TEXT NOT NULL,
  payload JSONB DEFAULT '{}'
) PARTITION BY RANGE (created_at);

-- 3. Create monthly partitions for 2026
CREATE TABLE app.events_2026_01 PARTITION OF app.events FOR VALUES FROM ('2026-01-01') TO ('2026-02-01');
CREATE TABLE app.events_2026_02 PARTITION OF app.events FOR VALUES FROM ('2026-02-01') TO ('2026-03-01');
CREATE TABLE app.events_2026_03 PARTITION OF app.events FOR VALUES FROM ('2026-03-01') TO ('2026-04-01');
CREATE TABLE app.events_2026_04 PARTITION OF app.events FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');
CREATE TABLE app.events_2026_05 PARTITION OF app.events FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');
CREATE TABLE app.events_2026_06 PARTITION OF app.events FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
CREATE TABLE app.events_2026_07 PARTITION OF app.events FOR VALUES FROM ('2026-07-01') TO ('2026-08-01');
CREATE TABLE app.events_2026_08 PARTITION OF app.events FOR VALUES FROM ('2026-08-01') TO ('2026-09-01');
CREATE TABLE app.events_2026_09 PARTITION OF app.events FOR VALUES FROM ('2026-09-01') TO ('2026-10-01');
CREATE TABLE app.events_2026_10 PARTITION OF app.events FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');
CREATE TABLE app.events_2026_11 PARTITION OF app.events FOR VALUES FROM ('2026-11-01') TO ('2026-12-01');
CREATE TABLE app.events_2026_12 PARTITION OF app.events FOR VALUES FROM ('2026-12-01') TO ('2027-01-01');

-- 4. Create index on each partition (auto-created on partitioned table)
CREATE INDEX idx_events_created_at ON app.events (created_at);

-- 5. Migrate data
INSERT INTO app.events (id, created_at, event_type, payload)
SELECT id, created_at, event_type, payload FROM app.events_old;

-- 6. Restore sequence
SELECT setval(pg_get_serial_sequence('app.events', 'id'), (SELECT max(id) FROM app.events));

-- 7. Drop old table
DROP TABLE app.events_old;

COMMIT;
SQL

